#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <string.h>

#include "scenery_route.h"

/* As route_table_store writes it: a straight push, a turn, a straight pull. */
static const char *const file =
    "### This is the BetterPushback segment table ###\n"
    "### This file is automatically generated. DO NOT EDIT! ###\n"
    "\n"
    "route\n"
    "  seg 0 47.00000000000000000 15.00000000000000000 90.0 "
    "47.00000000000000000 14.99960000000000000 90.0 1 0\n"
    "  seg 1 47.00000000000000000 14.99960000000000000 90.0 "
    "47.00020000000000000 14.99940000000000000 0.0 1 30.000 0 1\n"
    "  seg 0 47.00020000000000000 14.99940000000000000 0.0 "
    "47.00040000000000000 14.99940000000000000 0.0 0 1\n"
    "\n"
    "route\n"
    "  seg 0 47.10000000000000000 15.10000000000000000 180.0 "
    "47.10040000000000000 15.10000000000000000 180.0 1 0\n";

static bool
near(double a, double b, double tol)
{
    return (fabs(a - b) <= tol);
}

static void
test_a_route_file_is_read(void)
{
    bp_scenery_route_t routes[4];
    int n = bp_scenery_routes_parse(file, routes, 4);

    assert(n == 2);
    assert(near(routes[0].lat, 47.0, 1e-12) && near(routes[0].hdg, 90, 1e-12));
    assert(routes[0].n == 3);
    assert(routes[0].ends[0].backward && !routes[0].ends[0].user_placed);
    assert(routes[0].ends[1].user_placed);
    assert(!routes[0].ends[2].backward);
    assert(routes[1].n == 1);

    /* Fewer places than routes: as many as fit. */
    assert(bp_scenery_routes_parse(file, routes, 1) == 1);
    assert(bp_scenery_routes_parse("", routes, 4) == 0);
    assert(bp_scenery_routes_parse(NULL, routes, 4) == 0);
}

static void
test_a_broken_route_is_left_out(void)
{
    bp_scenery_route_t routes[4];
    char text[2048];

    (void)snprintf(text, sizeof (text), "route\n  seg 0 47 15 90 47 15\n%s",
        file);
    assert(bp_scenery_routes_parse(text, routes, 4) == 2);
    /* An unknown keyword spoils only its route. */
    (void)snprintf(text, sizeof (text), "%s  bogus 1 2 3\n", file);
    assert(bp_scenery_routes_parse(text, routes, 4) == 1);
    /* A route with no segments is no route. */
    assert(bp_scenery_routes_parse("route\nroute\n", routes, 4) == 0);
    /* A heading out of range. */
    assert(bp_scenery_routes_parse("route\n  seg 0 47 15 400 47 15 90 1 0\n",
        routes, 4) == 0);
}

static void
test_only_routes_starting_at_the_aircraft_are_offered(void)
{
    bp_scenery_route_t routes[4];

    assert(bp_scenery_routes_parse(file, routes, 4) == 2);
    assert(bp_scenery_route_matches(&routes[0], 47.0, 15.0, 90));
    assert(near(routes[0].distance, 0, 1e-6));
    /* Ten metres away and a little turned: still this stand. */
    assert(bp_scenery_route_matches(&routes[0], 47.00009, 15.0, 110));
    /* Facing the other way, or at the next stand. */
    assert(!bp_scenery_route_matches(&routes[0], 47.0, 15.0, 270));
    assert(!bp_scenery_route_matches(&routes[0], 47.0005, 15.0, 90));
    /* Across north. */
    routes[1].hdg = 355;
    assert(bp_scenery_route_matches(&routes[1], 47.1, 15.1, 10));
}

static void
test_nearest_first(void)
{
    bp_scenery_route_t routes[3];

    memset(routes, 0, sizeof (routes));
    routes[0].distance = 12;
    routes[1].distance = 3;
    routes[2].distance = 7;
    bp_scenery_routes_sort(routes, 3);
    assert(routes[0].distance == 3 && routes[2].distance == 12);
}

static void
test_the_positions_follow_the_wed_nodes(void)
{
    bp_scenery_route_t routes[4];
    bp_ext_pose_t poses[8];
    int n;

    assert(bp_scenery_routes_parse(file, routes, 4) == 2);
    /* Marked nodes: the turn's end and the pull's end. */
    n = bp_scenery_route_poses(&routes[0], poses, 8);
    assert(n == 2);
    assert(near(poses[0].lat, 47.0002, 1e-12) && poses[0].backward);
    assert(near(poses[1].lat, 47.0004, 1e-12) && !poses[1].backward);
    assert(poses[1].kind == BP_EXT_POSE_POSITION);

    /* Converted before nodes were marked: each change of direction. */
    for (int i = 0; i < routes[0].n; i++)
        routes[0].ends[i].user_placed = false;
    n = bp_scenery_route_poses(&routes[0], poses, 8);
    assert(n == 2);
    assert(near(poses[0].lat, 47.0002, 1e-12));      /* end of the push */

    /* One segment: its end. */
    assert(bp_scenery_route_poses(&routes[1], poses, 8) == 1);
    assert(near(poses[0].hdg, 180, 1e-12));
    assert(bp_scenery_route_poses(&routes[0], poses, 1) == 1);
}

int
main(void)
{
    test_a_route_file_is_read();
    test_a_broken_route_is_left_out();
    test_only_routes_starting_at_the_aircraft_are_offered();
    test_nearest_first();
    test_the_positions_follow_the_wed_nodes();
    printf("scenery route tests passed\n");
    return (0);
}
